'use client';

import { useEffect, useRef, useState } from 'react';
import type { ReactNode } from 'react';

const STEPS = [
  { n: '01', title: 'Upload', desc: 'The agency uploads the final document or permit to GovChain.' },
  { n: '02', title: 'Seal', desc: 'A cryptographic fingerprint of the document is written to the ledger.' },
  { n: '03', title: 'Publish', desc: 'A verification code is issued and attached to the public record.' },
  { n: '04', title: 'Verify', desc: 'Anyone can check the code against the sealed fingerprint at any time.' },
];

function RevealOnScroll({ children, className = '' }: { children: ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setVisible(true); },
      { threshold: 0.15 }
    );
    setTimeout(() => io.observe(el), 50);
    return () => io.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      className={`transition-all duration-700 ease-out ${
        visible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-7'
      } ${className}`}
    >
      {children}
    </div>
  );
}

export function GovchainSections() {
  return (
    <>
      {/* How Sealing Works */}
      <section
        id="seal"
        className="border-y border-zinc-900 bg-zinc-950/50 py-28"
      >
        <div className="max-w-[1240px] mx-auto px-12 max-md:px-[22px]">
          <p className="text-center text-[10px] font-black uppercase tracking-[0.16em] text-blue-500 mb-3">
            How Sealing Works
          </p>
          <h2 className="text-center text-3xl font-black mb-12 text-[#eef1f8] tracking-tight">
            From filed document to public record.
          </h2>
          <div className="grid grid-cols-4 max-md:grid-cols-1">
            {STEPS.map((s, i) => (
              <RevealOnScroll
                key={s.n}
                className={[
                  'px-5 py-1',
                  i > 0
                    ? 'border-l border-blue-500/30 max-md:border-l-0 max-md:border-t max-md:border-blue-500/30 max-md:pt-5 max-md:mt-5'
                    : '',
                ].join(' ')}
              >
                <div className="font-mono text-[13px] font-bold text-blue-500 mb-2.5">{s.n}</div>
                <div className="font-bold text-[15px] mb-2 text-[#eef1f8]">{s.title}</div>
                <div className="text-[#a9b4cc] text-[13px] leading-relaxed">{s.desc}</div>
              </RevealOnScroll>
            ))}
          </div>
        </div>
      </section>

      {/* Public Verification */}
      <section id="verify" className="py-28">
        <div className="max-w-[1240px] mx-auto px-12 max-md:px-[22px] grid grid-cols-[0.9fr_1.1fr] max-md:grid-cols-1 gap-[70px] items-center">
          <RevealOnScroll className="rounded-md border border-blue-500/20 bg-gradient-to-b from-white/[0.035] to-white/[0.015] p-8">
            <div className="font-bold text-base mb-3.5 text-[#eef1f8]">Public verification</div>
            <div className="text-[#a9b4cc] text-sm leading-relaxed">
              Anyone with a document ID or scan code can confirm the sealed version matches what's on
              file — no login required.
            </div>
          </RevealOnScroll>
          <RevealOnScroll>
            <p className="text-[10px] font-black uppercase tracking-[0.16em] text-blue-500 mb-3">
              Public Verification
            </p>
            <h2 className="text-[30px] font-black mb-4 text-[#eef1f8] tracking-tight leading-tight">
              Transparency, without the paperwork chase.
            </h2>
            <p className="text-[#a9b4cc] leading-relaxed text-base">
              A resident, journalist, or auditor can check that a public record is exactly what the
              agency filed — down to the timestamp.
            </p>
          </RevealOnScroll>
        </div>
      </section>
    </>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import {
  Sparkles,
  Download,
  CreditCard,
  CheckCircle,
  Shield,
  Zap,
  Lock,
  Package,
  Vote,
  ArrowRight,
  Palette,
  Eye,
  Activity,
  ShieldCheck,
  ScanLine,
  Coins,
} from 'lucide-react';
import { createClient } from '@/utils/supabase/client';
import { User } from '@supabase/supabase-js';
import { MODES, FalaiPreset, QRONModeConfig } from '@/lib/types';
import { PLANS } from '@/lib/plans';
import dynamic from 'next/dynamic';
import Image from 'next/image';

import { FeaturedQRONs } from '@/components/FeaturedQRONs';
import { LeadCapturePopup } from '@/components/LeadCapturePopup';
import { SocialShareCTA } from '@/components/SocialShareCTA';
import { TrustRail } from '@/components/TrustRail';
import { RoiCalculator } from '@/components/RoiCalculator';
import { LiveStatsCounter } from '@/components/LiveStatsCounter';
import { StickyConversionBar } from '@/components/StickyConversionBar';

const StaticImageGallery = dynamic(
  () =>
    import('@/components/StaticImageGallery').then((m) => m.StaticImageGallery),
  { ssr: false }
);

export function QronHome() {
  const hasSupabaseEnv =
    Boolean(process.env.NEXT_PUBLIC_SUPABASE_URL) &&
    Boolean(process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY);
  const supabase = hasSupabaseEnv ? createClient() : null;

  const [targetUrl, setTargetUrl] = useState('');
  const [prompt, setPrompt] = useState('');
  const [selectedMode, setSelectedMode] = useState<QRONModeConfig>(MODES[0]);
  const [presetId, setPresetId] = useState<string>('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [downloadName, setDownloadName] = useState('');
  const [error, setError] = useState('');
  const [userTier, setUserTier] = useState('free');
  const [guestUsed, setGuestUsed] = useState(0);
  const [showEmailCapture, setShowEmailCapture] = useState(false);
  const [captureEmail, setCaptureEmail] = useState('');
  const [emailSaved, setEmailSaved] = useState(false);
  const [isMagicGenerating, setIsMagicGenerating] = useState(false);
  const [showScanTest, setShowScanTest] = useState(false);

  const handleMagicTry = async (brandName: string) => {
    const examples: Record<string, { url: string; prompt: string; mode: string }> = {
      Tesla: {
        url: 'https://tesla.com',
        prompt: 'Futuristic glass aesthetic, red glowing circuits, minimalist cybertech',
        mode: 'living'
      },
      Nike: {
        url: 'https://nike.com',
        prompt: 'Abstract liquid motion, athletic textures, vibrant energetic pulses',
        mode: 'kinetic'
      },
      Rolex: {
        url: 'https://rolex.com',
        prompt: 'Luxury gold watch mechanisms, intricate gear details, emerald green and gold hues',
        mode: 'holographic'
      },
      Hermes: {
        url: 'https://hermes.com',
        prompt: 'Hermes Birkin leather texture, signature orange and brown tones, luxury equestrian aesthetic',
        mode: 'living'
      },
      Chanel: {
        url: 'https://chanel.com',
        prompt: 'Chanel classic flap quilting, interlocking CC logo gold metal, black and white pearls',
        mode: 'holographic'
      },
      Moderna: {
        url: 'https://modernatx.com',
        prompt: 'mRNA molecular structures, medical laboratory aesthetics, clean sterile blue and white',
        mode: 'layered'
      },
      Gilmore: {
        url: 'https://gilmorecarmuseum.org',
        prompt: '1929 Duesenberg Model J at the Gilmore Car Museum. Elegant museum photography, soft studio lighting.',
        mode: 'living'
      },
      Metrc: {
        url: 'https://metrc.com',
        prompt: 'StrainChain Bio Jungle AI QR. Organic forest textures, cannabis leaf veins, deep emerald green.',
        mode: 'living'
      }
    };

    const ex = examples[brandName] || examples.Tesla;
    setTargetUrl(ex.url);
    setPrompt(ex.prompt);
    const mode = MODES.find(m => m.id === ex.mode);
    if (mode) setSelectedMode(mode);

    setIsMagicGenerating(true);
    // Auto-scroll to generator
    document.getElementById('generator-section')?.scrollIntoView({ behavior: 'smooth' });

    // Simulate thinking/auto-start
    setTimeout(() => {
      if (user) handleGenerate();
      else handleGuestGenerate();
      setIsMagicGenerating(false);
    }, 1500);
  };

  const saveGuestEmail = async () => {
    if (!captureEmail || !captureEmail.includes('@')) return;
    try {
      await fetch(
        `${process.env.NEXT_PUBLIC_SUPABASE_URL}/rest/v1/email_leads`,
        {
          method: 'POST',
          headers: {
            apikey: process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '',
            Authorization:
              'Bearer ' + (process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || ''),
            'Content-Type': 'application/json',
            'Prefer': 'return=minimal',
          },
          body: JSON.stringify({
            email: captureEmail,
            source: 'guest_generate',
            metadata: { style: selectedMode?.id },
          }),
        }
      );
      setEmailSaved(true);
      setTimeout(() => setShowEmailCapture(false), 1500);
    } catch {}
  };

  const handleGuestGenerate = async () => {
    if (!targetUrl) {
      setError('Please enter a URL.');
      return;
    }
    if (guestUsed >= 2) {
      setError('Free limit reached. Sign up for more generations.');
      return;
    }
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const style = selectedMode?.id || 'space';
      const res = await fetch(
        'https://qron-ai-api.undone-k.workers.dev/v1/generate',
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            url: targetUrl,
            style,
            prompt: prompt || undefined,
          }),
        }
      );
      const d = await res.json();
      const img = d.previewUrl || d.downloadUrl || d.imageUrl || d.url;
      if (img) {
        setResult(img);
        setDownloadName(`qron-${selectedMode.id}-${new Date().getTime()}.png`);
        setGuestUsed((prev) => {
          const next = prev + 1;
          if (next >= 1) setTimeout(() => setShowEmailCapture(true), 2000);
          return next;
        });
      } else {
        setError(d.error || 'Generation failed. Try again.');
      }
    } catch {
      setError('Network error. Try again.');
    } finally {
      setLoading(false);
    }
  };
  const [generationsUsed, setGenerationsUsed] = useState(0);
  const [generationsLimit, setGenerationsLimit] = useState(10);
  const [user, setUser] = useState<User | null>(null);
  const [presets, setPresets] = useState<FalaiPreset[]>([]);
  const [selectedPreset, setSelectedPreset] = useState<FalaiPreset | null>(
    null
  );

  useEffect(() => {
    const fetchUserData = async () => {
      if (!supabase) return;
      const {
        data: { user: authUser },
      } = await supabase.auth.getUser();
      setUser(authUser);
      if (authUser) {
        const { data: profile, error: profileError } = await supabase
          .from('profiles')
          .select('tier, generations_used, generations_limit')
          .eq('user_id', authUser.id)
          .single();
        if (profile && !profileError) {
          setUserTier(profile.tier);
          setGenerationsUsed(profile.generations_used);
          setGenerationsLimit(profile.generations_limit);
        }
      }
    };

    const fetchPresets = async () => {
      try {
        const res = await fetch('/api/presets');
        if (res.ok) {
          const data: FalaiPreset[] = await res.json();
          setPresets(data);
          if (data[0]) {
            setSelectedPreset(data[0]);
            setPresetId(data[0].id);
          }
        }
      } catch {
                // silently fail — presets will be empty
      }
    };

    fetchUserData();
    fetchPresets();
  }, [supabase]);

  const isTierSufficient = (requiredTier: string) => {
    if (requiredTier === 'free') return true;
    if (
      requiredTier === 'pro' &&
      (userTier === 'pro' || userTier === 'enterprise')
    )
      return true;
    if (requiredTier === 'enterprise' && userTier === 'enterprise') return true;
    return false;
  };

  const handleGenerate = async () => {
    if (!targetUrl || !prompt || !selectedMode || !presetId) {
      setError('Please fill in all required fields.');
      return;
    }
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const response = await fetch('/api/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          targetUrl,
          prompt,
          presetId: selectedPreset?.id,
          mode: selectedMode.id,
        }),
      });
      const data = await response.json();
      if (response.ok) {
        setResult(data.qron.imageUrl);
        setDownloadName(`qron-${selectedMode.id}-${new Date().getTime()}.png`);
        setGenerationsUsed((prev) => prev + 1);
      } else {
        setError(data.message || 'Generation failed.');
      }
    } catch (err) {
      setError('Network error or unexpected response.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleUpgrade = async (planId: string) => {
    const plan = PLANS.find((p) => p.id === planId);
    if (!plan || plan.price === 0) {
      window.location.assign('/login');
      return;
    }
    if (!plan.stripe_price_id) {
      window.location.assign('mailto:Z@authichain.com');
      return;
    }
    try {
      const res = await fetch('/api/checkout', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ planId, email: user?.email }),
      });
      const { url, error: checkoutError } = await res.json();
      if (url) window.location.assign(url);
      else if (plan.stripe_payment_link)
        window.location.assign(plan.stripe_payment_link);
      else if (checkoutError) setError(checkoutError);
    } catch {
      if (plan.stripe_payment_link)
        window.location.assign(plan.stripe_payment_link);
      else setError('Could not start checkout. Please try again.');
    }
  };

  const userPlan = PLANS.find((p) => p.id === userTier) || PLANS[0];

  return (
    <div className="min-h-screen protocol-bg text-white">
      <div className="container mx-auto px-4 py-12 max-w-6xl">
        {/* Hero */}
        <div className="text-center mb-14">
          {/* Protocol badge */}
          <div className="flex justify-center mb-6">
            <span className="protocol-badge">
              <Shield className="w-3 h-3" />
              Creative Layer of the AuthiChain Protocol
            </span>
          </div>

          {/* Hero QR Art */}
          <div className="flex justify-center mb-6 animate-float">
            <Image
              src="/media/samples/01_flux_qron_space.png"
              alt="QRON Space Artistic AI"
              width={220}
              height={220}
              priority
              style={{ filter: 'drop-shadow(0 0 32px rgba(255,215,0,0.35))' }}
            />
          </div>

          <h1 className="text-5xl md:text-7xl font-extrabold mb-3 leading-[1.02] tracking-tight">
            <span className="gold-text">QRON</span>
            <span className="mt-3 block text-2xl md:text-4xl font-bold text-white leading-tight">
              AI-generated QR art that actually scans
            </span>
          </h1>
          <p
            className="text-lg md:text-xl font-light mb-3"
            style={{ color: '#c8c8c8' }}
          >
            Turn any link into a branded work of art — cryptographically signed and scannable from any camera.
          </p>
          <p
            className="text-base max-w-xl mx-auto"
            style={{ color: '#6b6b6b' }}
          >
            Where authentication meets artistry — every QRON is signed by the{' '}
            <a
              href="https://authichain.com"
              target="_blank"
              rel="noreferrer"
              style={{
                color: '#c9a227',
                textDecoration: 'none',
                fontWeight: 600,
              }}
            >
              AuthiChain Protocol
            </a>{' '}
            and verifiable by anyone, anywhere.
          </p>

          {/* Magic Try Buttons */}
          <div className="flex flex-wrap justify-center gap-4 mt-8">
             <span className="w-full text-[10px] font-black uppercase tracking-[0.2em] text-zinc-700 mb-2">Instant Demo:</span>
             {['Tesla', 'Nike', 'Rolex', 'Hermes', 'Chanel', 'Moderna', 'Gilmore', 'Metrc'].map(brand => (
               <button
                 key={brand}
                 onClick={() => handleMagicTry(brand)}
                 disabled={isMagicGenerating || loading}
                 className="px-6 py-2 rounded-full bg-zinc-900 border border-zinc-800 hover:border-gold/50 transition-all text-xs font-black uppercase tracking-widest text-zinc-400 hover:text-white"
               >
                 Try for {brand}
               </button>
             ))}
          </div>
          <p className="text-center text-[9px] uppercase tracking-widest text-zinc-700 mt-3">
            Unaffiliated demo — brand names shown for illustration only, no endorsement implied
          </p>

          {/* Stat strip */}
          <div className="flex flex-wrap justify-center gap-8 mt-12">
            {[
              {
                icon: <Zap className="w-4 h-4" />,
                stat: 'Scannable',
                label: 'AI art from any camera',
              },
              {
                icon: <Lock className="w-4 h-4" />,
                stat: 'Ed25519',
                label: 'signed & Polygon-anchored',
              },
              {
                icon: <Shield className="w-4 h-4" />,
                stat: 'Editable',
                label: 'redirects — no reprint',
              },
            ].map(({ icon, stat, label }) => (
              <div
                key={label}
                className="flex items-center gap-2"
                style={{ color: '#9e9e9e', fontSize: '13px' }}
              >
                <span style={{ color: '#c9a227' }}>{icon}</span>
                <span style={{ color: '#e8c547', fontWeight: 700 }}>
                  {stat}
                </span>
                <span>{label}</span>
              </div>
            ))}
          </div>

          {/* New Trust Row */}
          <div className="mt-16 flex flex-col items-center">
             <div className="flex items-center gap-4 text-[9px] font-black uppercase tracking-[0.3em] text-zinc-600 mb-6">
                <span>Polygon PoS</span>
                <div className="w-1 h-1 rounded-full bg-zinc-800" />
                <span>Ed25519 Signed</span>
                <div className="w-1 h-1 rounded-full bg-zinc-800" />
                <span>Editable Redirects</span>
             </div>
             <div className="px-8 py-4 rounded-2xl bg-gold/5 border border-gold/10 inline-flex items-center gap-6">
                <div className="text-left border-r border-gold/10 pr-6">
                    <p className="text-[10px] font-black text-gold uppercase tracking-widest mb-1">On-chain provenance</p>
                    <p className="text-xl font-black text-white tracking-tighter">Signed <span className="text-zinc-500 font-medium text-xs tracking-normal uppercase ml-1">&amp; verifiable by anyone</span></p>
                </div>
                <div className="flex items-center gap-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest">
                   <CheckCircle className="w-4 h-4 text-green-500" />
                   Secured by the AuthiChain Protocol
                </div>
             </div>
          </div>
        </div>

        {/* Social-proof / trust rail — directly below the hero */}
        <div className="mb-12 -mx-4 md:mx-0 md:rounded-2xl md:overflow-hidden">
          <TrustRail accent="#F59E0B" />
        </div>

        {/* Generator */}
        <div id="generator-section" className="protocol-card p-8 mb-12 relative overflow-hidden">
          {/* Magic Loading Overlay */}
          {(loading || isMagicGenerating) && (
            <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center p-8 text-center animate-in fade-in duration-300">
               <div className="relative mb-6">
                  <div className="w-20 h-20 rounded-full border-2 border-gold/20 border-t-gold animate-spin" />
                  <Sparkles className="absolute inset-0 m-auto w-8 h-8 text-gold animate-pulse" />
               </div>
               <h3 className="text-xl font-black uppercase tracking-tighter gold-text mb-2">
                 {isMagicGenerating ? 'Synchronizing Brand Assets...' : 'Creating Cinematic QRON...'}
               </h3>
               <p className="text-zinc-500 text-xs font-bold uppercase tracking-[0.2em] max-w-xs leading-loose">
                 Anchoring to AuthiChain Truth Network • AI Inference in progress • ~15s
               </p>
            </div>
          )}

          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-white">Create Your QRON</h2>
            <span className="protocol-badge">
              <Shield className="w-3 h-3" />
              AuthiChain Protocol
            </span>
          </div>

          {/* Email capture modal after guest generation */}
          {showEmailCapture && !emailSaved && (
            <div
              style={{
                position: 'fixed',
                inset: 0,
                background: 'rgba(0,0,0,0.75)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 1000,
              }}
            >
              <div
                style={{
                  background: '#111',
                  border: '1px solid #c9a227',
                  borderRadius: 16,
                  padding: 32,
                  maxWidth: 420,
                  width: '90%',
                  textAlign: 'center',
                }}
              >
                <div style={{ fontSize: 32, marginBottom: 8 }}>🎨</div>
                <h3
                  style={{
                    color: '#c9a227',
                    fontWeight: 900,
                    fontSize: '1.2rem',
                    marginBottom: 8,
                  }}
                >
                  Your QR art is ready!
                </h3>
                <p style={{ color: '#aaa', fontSize: 14, marginBottom: 20 }}>
                  Enter your email to save it permanently + get 2 more free
                  generations
                </p>
                <input
                  type="email"
                  value={captureEmail}
                  onChange={(e) => setCaptureEmail(e.target.value)}
                  placeholder="your@email.com"
                  onKeyDown={(e) => e.key === 'Enter' && saveGuestEmail()}
                  style={{
                    width: '100%',
                    padding: '12px 16px',
                    borderRadius: 8,
                    border: '1px solid #333',
                    background: '#0a0a0a',
                    color: '#fff',
                    fontSize: 15,
                    marginBottom: 12,
                    outline: 'none',
                  }}
                />
                <button
                  onClick={saveGuestEmail}
                  style={{
                    width: '100%',
                    padding: '12px',
                    background: '#c9a227',
                    color: '#000',
                    border: 'none',
                    borderRadius: 8,
                    fontSize: 15,
                    fontWeight: 700,
                    cursor: 'pointer',
                    marginBottom: 8,
                  }}
                >
                  Save My QR Code
                </button>
                <button
                  onClick={() => setShowEmailCapture(false)}
                  style={{
                    background: 'none',
                    border: 'none',
                    color: '#555',
                    fontSize: 13,
                    cursor: 'pointer',
                  }}
                >
                  No thanks, I&apos;ll skip
                </button>
              </div>
            </div>
          )}
          {showEmailCapture && emailSaved && (
            <div
              style={{
                position: 'fixed',
                inset: 0,
                background: 'rgba(0,0,0,0.75)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                zIndex: 1000,
              }}
            >
              <div
                style={{
                  background: '#111',
                  border: '1px solid #4ade80',
                  borderRadius: 16,
                  padding: 32,
                  textAlign: 'center',
                }}
              >
                <div style={{ fontSize: 48, marginBottom: 8 }}>✅</div>
                <h3 style={{ color: '#4ade80', fontWeight: 900 }}>
                  Saved! Check your email.
                </h3>
              </div>
            </div>
          )}
          {/* Tier / limit indicator */}
          <div
            className="flex items-center justify-between mb-6 px-4 py-3 rounded-lg"
            style={{
              background: 'rgba(201,162,39,0.06)',
              border: '1px solid rgba(201,162,39,0.15)',
            }}
          >
            <span style={{ color: '#9e9e9e', fontSize: '13px' }}>
              Plan:{' '}
              <span style={{ color: '#e8c547', fontWeight: 700 }}>
                {userPlan?.name.toUpperCase()}
