import { NextResponse } from 'next/server';
import { generateGilmoreArt, GilmoreArtRequest } from '@/lib/industrial/gilmore-pipeline';
import { createClient } from '@/utils/supabase/server';

function getErrorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

export async function POST(request: Request) {
  try {
    const supabase = await createClient();
    const { data: { session } } = await supabase.auth.getSession();

    // In a real scenario, we might want to restrict this to Theater 3/Enterprise users
    // For the demo, we'll allow authenticated users.

    const body: GilmoreArtRequest = await request.json();
    const { carModel, year, destinationUrl } = body;

    if (!carModel || !year || !destinationUrl) {
      return NextResponse.json({ message: 'Missing required fields' }, { status: 400 });
    }

    const result = await generateGilmoreArt(body);

    return NextResponse.json({
      success: true,
      qron: result,
    });
  } catch (error) {
    console.error('Gilmore Pipeline Error:', error);
    return NextResponse.json(
      {
        message: getErrorMessage(error, 'Error generating automotive art'),
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin as supabase } from '@/lib/supabase-admin';

interface UsageStatRow {
  total_scans?: number | null;
}

interface SocialProofResponse {
  stats: {
    total_users: number;
    total_qrons: number;
    total_scans: number;
  };
  trust_badges: Array<{ label: string; icon: string }>;
  generated_at: string;
}

// Cache for 1 hour to avoid repeated DB calls on landing page
let cache: { data: SocialProofResponse; ts: number } | null = null;
const CACHE_TTL = 3600000;

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : 'Unknown error';
}

export async function GET(req: NextRequest) {
  try {
    if (cache && Date.now() - cache.ts < CACHE_TTL) {
      return NextResponse.json(cache.data);
    }

    const [usersRes, qronsRes, scansRes] = await Promise.all([
      supabase.from('profiles').select('id', { count: 'exact', head: true }),
      supabase.from('qrons').select('id', { count: 'exact', head: true }),
      supabase.from('usage_stats').select('total_scans'),
    ]);

    const totalUsers = usersRes.count || 0;
    const totalQrons = qronsRes.count || 0;
    const scanRows = (scansRes.data ?? []) as UsageStatRow[];
    const totalScans = scanRows.reduce((sum, row) => sum + (row.total_scans || 0), 0);

    // Real counts only. Do not floor these to invented minimums and do not add
    // hardcoded ratings, review counts, or country totals — an authenticity
    // product cannot publish unverifiable numbers about itself. If a figure is
    // not measured from the ledger, it does not belong in this response.
    const stats = {
      total_users: totalUsers,
      total_qrons: totalQrons,
      total_scans: totalScans,
    };

    const proof: SocialProofResponse = {
      stats,
      // Only badges backed by something checkable. SOC 2 was removed: no report
      // exists. Uptime was removed: no measured figure is read here.
      trust_badges: [
        { label: 'Stripe Secured', icon: 'stripe' },
        { label: 'GDPR Compliant', icon: 'gdpr' },
      ],
      generated_at: new Date().toISOString(),
    };

    cache = { data: proof, ts: Date.now() };
    return NextResponse.json(proof);
  } catch (err) {
    return NextResponse.json({ error: getErrorMessage(err) }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin as supabase } from '@/lib/supabase-admin';
import { resend } from '@/lib/resend';

interface TrialReminderUser {
  email?: string | null;
  name?: string | null;
}

interface TrialReminderRow {
  user_id: string;
  trial_start: string;
  users?: TrialReminderUser | null;
}

// Called daily by Vercel cron or n8n
// Sends reminder emails to trial users at day 10 and day 13
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  if (authHeader !== `****** {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const now = new Date();
  const day10Start = new Date(now.getTime() - 10 * 24 * 60 * 60 * 1000);
  const day10End = new Date(day10Start.getTime() + 24 * 60 * 60 * 1000);
  const day13Start = new Date(now.getTime() - 13 * 24 * 60 * 60 * 1000);
  const day13End = new Date(day13Start.getTime() + 24 * 60 * 60 * 1000);

  const { data: day10Users } = await supabase
    .from('subscriptions')
    .select('user_id, trial_start, users(email, name)')
    .eq('status', 'trialing')
    .gte('trial_start', day10Start.toISOString())
    .lt('trial_start', day10End.toISOString());

  const { data: day13Users } = await supabase
    .from('subscriptions')
    .select('user_id, trial_start, users(email, name)')
    .eq('status', 'trialing')
    .gte('trial_start', day13Start.toISOString())
    .lt('trial_start', day13End.toISOString());

  let sent = 0;

  const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const day10Rows = (day10Users ?? []) as TrialReminderRow[];
  const day13Rows = (day13Users ?? []) as TrialReminderRow[];

  for (const user of day10Rows) {
    const email = user.users?.email;
    const name = esc(user.users?.name || 'there');
    if (!email) continue;
    await resend.emails.send({
      from: 'QRON <noreply@qron.space>',
      to: email,
      subject: '4 days left on your QRON Pro trial',
      html: `<h2>Hi ${name},</h2><p>You have <strong>4 days left</strong> on your QRON Pro trial. Here's what you've been able to do so far:</p><ul><li>Create AI-styled QR codes</li><li>Track scan analytics</li><li>Use custom redirect domains</li></ul><p>To keep all these features after your trial ends, <a href="https://qron.space/pricing">upgrade to Pro now</a> — starting at just $29/mo.</p><p>Questions? Just reply to this email.</p>`,
    }).catch(() => {});
    sent++;
  }

  for (const user of day13Rows) {
    const email = user.users?.email;
    const name = esc(user.users?.name || 'there');
    if (!email) continue;
    await resend.emails.send({
      from: 'QRON <noreply@qron.space>',
      to: email,
      subject: 'Your QRON trial ends tomorrow — keep your QR codes',
      html: `<h2>Hi ${name},</h2><p>Your QRON Pro trial ends <strong>tomorrow</strong>. After that, you'll lose access to:</p><ul><li>AI-generated QR art styles</li><li>Scan analytics &amp; heatmaps</li><li>Custom redirect domains</li><li>Bulk export</li></ul><p><a href="https://qron.space/pricing" style="background:#6366f1;color:white;padding:12px 24px;border-radius:6px;text-decoration:none;display:inline-block;">Upgrade Now — from $29/mo</a></p><p>Use code <strong>EARLYBIRD20</strong> for 20% off your first 3 months.</p>`,
    }).catch(() => {});
    sent++;
  }

  return NextResponse.json({
    success: true,
    day10_reminders: day10Rows.length,
    day13_reminders: day13Rows.length,
    total_sent: sent,
    run_at: now.toISOString(),
  });
}

import { NextRequest, NextResponse } from 'next/server';

interface BulkCodeInput {
  name?: string;
  url?: string;
  type?: string;
  campaign_id?: string | null;
  style?: {
    foreground?: string;
    background?: string;
    logo?: boolean;
  };
}

export async function POST(req: NextRequest) {
  const body = await req.json() as { codes?: BulkCodeInput[] };
  const codes = body.codes;

  if (!Array.isArray(codes) || codes.length === 0) {
    return NextResponse.json({ error: 'codes array is required and must not be empty' }, { status: 400 });
  }

  if (codes.length > 500) {
    return NextResponse.json({ error: 'Maximum 500 QR codes per bulk request' }, { status: 400 });
  }

  const results = codes.map((code, index: number) => {
    if (!code.name || !code.url) {
      return {
        index,
        success: false,
        error: 'name and url are required for each code',
        input: code
      };
    }
    return {
      index,
      success: true,
      qr_code: {
        id: `qr_bulk_${Date.now()}_${index}`,
        name: code.name,
        url: code.url,
        short_url: `https://qron.space/r/${Buffer.from(crypto.getRandomValues(new Uint8Array(5))).toString('hex').slice(0, 8)}`,
        type: code.type || 'url',
        campaign_id: code.campaign_id || null,
        style: code.style || { foreground: '#000000', background: '#ffffff', logo: false },
        status: 'active',
        scans: 0,
        created_at: new Date().toISOString(),
        protocol: 'QRON'
      }
    };
  });

  const succeeded = results.filter(r => r.success);
  const failed = results.filter(r => !r.success);

  return NextResponse.json({
    success: true,
    processed: codes.length,
    created: succeeded.length,
    failed: failed.length,
    results,
    batch_id: `batch_${Date.now()}`,
    protocol: 'QRON'
  }, { status: 201 });
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const batch_id = searchParams.get('batch_id');

  return NextResponse.json({
