'use client';

import { useState, useEffect } from 'react';
import { format } from 'date-fns';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import { AlertCircle, CheckCircle, XCircle, Clock } from 'lucide-react';

interface InboundReply {
  id: string;
  leadEmail: string;
  senderName?: string;
  subject: string;
  sentiment: string;
  objectionType?: string;
  matchConfidence: number;
  status: string;
  createdAt: string;
  metadata?: Record<string, unknown>;
}

export default function InboundRepliesDashboard() {
  const [replies, setReplies] = useState<InboundReply[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [sentimentFilter, setSentimentFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [page, setPage] = useState(1);

  useEffect(() => {
    fetchReplies();
  }, [sentimentFilter, statusFilter, page]);

  const fetchReplies = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (sentimentFilter !== 'all') params.append('sentiment', sentimentFilter);
      if (statusFilter !== 'all') params.append('status', statusFilter);
      params.append('page', page.toString());
      params.append('limit', '20');

      const response = await fetch(`/api/dashboard/replies?${params}`);
      if (!response.ok) throw new Error('Failed to fetch replies');

      const data = await response.json();
      setReplies(data.replies || []);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  const updateReplyStatus = async (replyId: string, newStatus: string) => {
    try {
      const response = await fetch(`/api/dashboard/replies`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id: replyId, status: newStatus }),
      });

      if (!response.ok) throw new Error('Failed to update reply');
      fetchReplies();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    }
  };

  const getSentimentIcon = (sentiment: string) => {
    switch (sentiment) {
      case 'positive':
        return <CheckCircle className="h-4 w-4 text-green-600" />;
      case 'negative':
        return <XCircle className="h-4 w-4 text-red-600" />;
      case 'objection':
        return <AlertCircle className="h-4 w-4 text-orange-600" />;
      default:
        return <Clock className="h-4 w-4 text-gray-600" />;
    }
  };

  const getSentimentColor = (sentiment: string) => {
    switch (sentiment) {
      case 'positive':
        return 'bg-green-100 text-green-800';
      case 'negative':
        return 'bg-red-100 text-red-800';
      case 'objection':
        return 'bg-orange-100 text-orange-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'deal_won':
        return 'bg-green-100 text-green-800';
      case 'disqualified':
        return 'bg-red-100 text-red-800';
      case 'contacted':
        return 'bg-blue-100 text-blue-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  return (
    <div className="space-y-6 p-8">
      <div>
        <h1 className="text-3xl font-bold tracking-tight">Inbound Proposal Replies</h1>
        <p className="text-gray-600">Monitor and nurture customer responses to proposals</p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent className="flex gap-4">
          <div>
            <label className="text-sm font-medium text-gray-700">Sentiment</label>
            <Select value={sentimentFilter} onValueChange={setSentimentFilter}>
              <SelectTrigger className="w-40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Sentiments</SelectItem>
                <SelectItem value="positive">Positive</SelectItem>
                <SelectItem value="neutral">Neutral</SelectItem>
                <SelectItem value="negative">Negative</SelectItem>
                <SelectItem value="objection">Objection</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div>
            <label className="text-sm font-medium text-gray-700">Status</label>
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Statuses</SelectItem>
                <SelectItem value="new">New</SelectItem>
                <SelectItem value="contacted">Contacted</SelectItem>
                <SelectItem value="deal_won">Deal Won</SelectItem>
                <SelectItem value="disqualified">Disqualified</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {error && (
        <Card className="border-red-200 bg-red-50">
          <CardContent className="pt-6">
            <p className="text-red-800">{error}</p>
          </CardContent>
        </Card>
      )}

      <Card>
        <CardHeader>
          <CardTitle>Replies ({replies.length})</CardTitle>
          <CardDescription>Double-click a sentiment or status to update | Match confidence shows proposal match quality</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <p className="text-gray-600">Loading replies...</p>
          ) : replies.length === 0 ? (
            <p className="text-gray-600">No replies found</p>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>From</TableHead>
                    <TableHead>Subject</TableHead>
                    <TableHead>Sentiment</TableHead>
                    <TableHead>Match</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Received</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {replies.map((reply) => (
                    <TableRow key={reply.id} className="hover:bg-gray-50">
                      <TableCell className="font-medium">
                        <div>
                          <p>{reply.senderName || 'Unknown'}</p>
                          <p className="text-xs text-gray-600">{reply.leadEmail}</p>
                        </div>
                      </TableCell>
                      <TableCell>
                        <p className="max-w-xs truncate">{reply.subject}</p>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          {getSentimentIcon(reply.sentiment)}
                          <Badge className={getSentimentColor(reply.sentiment)}>
                            {reply.sentiment}
                            {reply.objectionType && ` - ${reply.objectionType}`}
                          </Badge>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div>
                          <p className="text-sm font-medium">{Math.round(reply.matchConfidence * 100)}%</p>
                          {reply.matchConfidence < 0.7 && (
                            <p className="text-xs text-orange-600">Review needed</p>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge className={getStatusColor(reply.status)}>{reply.status}</Badge>
                      </TableCell>
                      <TableCell className="text-sm text-gray-600">
                        {format(new Date(reply.createdAt), 'MMM d, HH:mm')}
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Button
                            size="sm"
                            variant="outline"
                            className="text-xs"
                            onClick={() => updateReplyStatus(reply.id, 'contacted')}
                          >
                            Mark Contacted
                          </Button>
                          <Button
                            size="sm"
                            variant="outline"
                            className="text-xs"
                            onClick={() => updateReplyStatus(reply.id, 'deal_won')}
                          >
                            Deal Won
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <div className="flex items-center justify-between">
        <p className="text-sm text-gray-600">Page {page}</p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page === 1}
          >
            Previous
          </Button>
          <Button variant="outline" onClick={() => setPage(page + 1)}>
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { Search, ExternalLink, Loader2, RadioTower } from 'lucide-react';

interface Opportunity {
  notice_id: string;
  title: string;
  agency: string | null;
  deadline: string | null;
  naics_code: string | null;
  description: string | null;
  fit_score: number | null;
  sam_url: string | null;
  scored_at: string | null;
}

function fitColor(score: number | null): string {
  if (score === null) return '#71717a';
  if (score >= 80) return '#22c55e';
  if (score >= 60) return '#eab308';
  return '#71717a';
}

export function OpportunityRadar() {
  const [opportunities, setOpportunities] = useState<Opportunity[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [errored, setErrored] = useState(false);
  const [q, setQ] = useState('');
  const [minFit, setMinFit] = useState(0);

  const load = useCallback(async (query: string, min: number) => {
    setLoading(true);
    setErrored(false);
    try {
      const params = new URLSearchParams({ limit: '20', min_fit: String(min) });
      if (query.trim()) params.set('q', query.trim());
      const res = await fetch(`/api/govchain/opportunities?${params}`, { cache: 'no-store' });
      if (!res.ok) throw new Error('request failed');
      const data = await res.json();
      setOpportunities(data.opportunities ?? []);
      setTotal(data.total ?? 0);
    } catch {
      setErrored(true);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(q, minFit);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const t = setTimeout(() => load(q, minFit), 350);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, minFit]);

  return (
    <section className="max-w-7xl mx-auto px-6 py-24 border-t border-zinc-900">
      <div className="flex items-center gap-2 mb-3">
        <RadioTower className="w-4 h-4 text-blue-500" />
        <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-500">
          Live Opportunity Radar
        </p>
      </div>
      <h2 className="text-3xl md:text-4xl font-black tracking-tighter mb-3">
        Real SAM.gov opportunities, scored today.
      </h2>
      <p className="max-w-2xl text-zinc-400 text-sm mb-10">
        These are live results from our automated ingestion + AI scoring pipeline — updated on every run,
        no demo data. {total > 0 && `${total} opportunities currently in the radar.`}
      </p>

      <div className="flex flex-col sm:flex-row gap-3 mb-8">
        <div className="relative flex-1">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-600" />
          <input
            type="text"
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search opportunity titles…"
            className="w-full rounded-xl border border-zinc-800 bg-zinc-950 pl-11 pr-4 py-3 text-sm text-white placeholder:text-zinc-600 focus:outline-none focus:border-blue-500/50"
          />
        </div>
        <select
          value={minFit}
          onChange={(e) => setMinFit(Number(e.target.value))}
          className="rounded-xl border border-zinc-800 bg-zinc-950 px-4 py-3 text-sm text-white focus:outline-none focus:border-blue-500/50"
        >
          <option value={0}>All fit scores</option>
