                <div className="flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-zinc-500 mb-2">
                  {o.agency && <span>{o.agency}</span>}
                  {o.naics_code && <span className="font-mono">NAICS {o.naics_code}</span>}
